<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ChevronLeft, Eye, EyeOff, Grid3X3, Layers3, Map, MousePointer2, Trash2, ZoomIn, ZoomOut } from 'lucide-vue-next'
import AppHeader from '../components/AppHeader.vue'
import { OBJECTS, TERRAIN, TOOLS } from '../constants.js'
import { exportMapPng } from '../services/portability.js'
import { useWorkspaceStore } from '../stores/workspace.js'

const store=useWorkspaceStore(),route=useRoute(),router=useRouter(),mapViewport=ref(),dragging=ref(false),pendingCells=new globalThis.Map(),roomAnchor=ref(null),inspectorTab=ref('layers')
const project=computed(()=>store.bundle?.project),cellSize=computed(()=>project.value?.cellSize||40),canvasStyle=computed(()=>({width:`${project.value.width*cellSize.value}px`,height:`${project.value.height*cellSize.value}px`,gridTemplateColumns:`repeat(${project.value.width},${cellSize.value}px)`,transform:`scale(${store.zoom})`}))
const layerVisible=(kind)=>store.bundle.layers.find((layer)=>layer.kind===kind)?.visible!==false
const terrainById=Object.fromEntries(TERRAIN.map((item)=>[item.id,item]))
const objectById=Object.fromEntries(OBJECTS.map((item)=>[item.id,item]))
const spriteStyle=(sprite)=>({backgroundPosition:`${(sprite%4)*100/3}% ${Math.floor(sprite/4)*100/3}%`})
const tileStyle=(id)=>spriteStyle(terrainById[id]?.sprite||0)
const objectStyle=(item)=>({...spriteStyle(objectById[item.assetId]?.sprite||0),left:`${item.x*cellSize.value}px`,top:`${item.y*cellSize.value}px`,width:`${cellSize.value}px`,height:`${cellSize.value}px`,transform:`rotate(${item.rotation||0}deg) scale(${item.scale||1})`})
onMounted(async()=>{await store.openProject(route.params.id);if(!store.bundle)router.replace('/')})
onBeforeUnmount(()=>{store.bundle=null})
function key(x,y){return `${x}:${y}`}
function addPending(x,y){pendingCells.set(key(x,y),{x,y})}
async function beginCell(x,y){
  if(store.activeTool==='object'){await store.placeObjects([{assetId:store.selectedObject,x,y}]);return}
  if(store.activeTool==='label'){const text=prompt('Label this place');if(text?.trim())await store.addLabels([{text:text.trim(),x,y}]);return}
  if(store.activeTool==='room'){if(!roomAnchor.value){roomAnchor.value={x,y};return}const left=Math.min(x,roomAnchor.value.x),top=Math.min(y,roomAnchor.value.y),width=Math.abs(x-roomAnchor.value.x)+1,height=Math.abs(y-roomAnchor.value.y)+1;roomAnchor.value=null;await store.createRooms([{x:left,y:top,width,height,terrain:store.selectedTerrain}]);return}
  dragging.value=true;pendingCells.clear();addPending(x,y)
}
function enterCell(x,y){if(dragging.value)addPending(x,y)}
async function finishStroke(){if(!dragging.value)return;dragging.value=false;const cells=[...pendingCells.values()];pendingCells.clear();if(store.activeTool==='terrain')await store.paintCells(cells,store.selectedTerrain);else if(store.activeTool==='wall')await store.drawWalls(cells);else if(store.activeTool==='erase')for(const cell of cells)await store.eraseAt(cell.x,cell.y)}
function selectObject(event,item){event.stopPropagation();store.selection={kind:'object',id:item.id};inspectorTab.value='selection'}
function selectLabel(event,item){event.stopPropagation();store.selection={kind:'label',id:item.id};inspectorTab.value='selection'}
async function download(){await exportMapPng(document.querySelector('.map-stage'),store.bundle)}
</script>
<template><main v-if="project" class="map-page" @pointerup="finishStroke" @pointerleave="finishStroke"><AppHeader workspace @export="download"/><section class="map-workspace"><aside class="map-palette"><div class="map-back"><button class="icon-button" title="All maps" @click="router.push('/')"><ChevronLeft/></button><div><small>Map builder</small><strong>{{project.title}}</strong></div></div><div class="tool-grid"><button v-for="tool in TOOLS" :key="tool.id" :class="['map-tool',{active:store.activeTool===tool.id}]" @click="store.activeTool=tool.id"><span>{{tool.id==='terrain'?'▦':tool.id==='room'?'▣':tool.id==='wall'?'╬':tool.id==='object'?'♜':tool.id==='label'?'T':'⌫'}}</span>{{tool.label}}</button></div><template v-if="['terrain','room'].includes(store.activeTool)"><div class="palette-heading"><strong>Terrain</strong><small>Hand-painted</small></div><div class="asset-grid terrain-assets"><button v-for="asset in TERRAIN" :key="asset.id" :class="['asset-button',{active:store.selectedTerrain===asset.id}]" :title="asset.label" @click="store.selectedTerrain=asset.id"><span class="terrain-swatch" :style="spriteStyle(asset.sprite)"></span><small>{{asset.label}}</small></button></div></template><template v-if="store.activeTool==='object'"><div class="palette-heading"><strong>Objects</strong><small>Top-down</small></div><div class="asset-grid object-assets"><button v-for="asset in OBJECTS" :key="asset.id" :class="['asset-button',{active:store.selectedObject===asset.id}]" :title="asset.label" @click="store.selectedObject=asset.id"><span class="object-swatch" :style="spriteStyle(asset.sprite)"></span><small>{{asset.label}}</small></button></div></template><div v-if="store.activeTool==='room'" class="tool-hint">{{roomAnchor?'Choose the opposite corner.':'Choose the first corner of the room.'}}</div></aside><section class="map-canvas-shell"><div class="map-toolbar"><button class="button" :class="{active:store.showGrid}" @click="store.showGrid=!store.showGrid"><Grid3X3/> Grid</button><button class="button" :class="{active:store.playerView}" @click="store.playerView=!store.playerView"><Eye/> Player view</button><span class="toolbar-divider"></span><button class="icon-button" title="Zoom out" @click="store.zoom=Math.max(.4,store.zoom-.1)"><ZoomOut/></button><span>{{Math.round(store.zoom*100)}}%</span><button class="icon-button" title="Zoom in" @click="store.zoom=Math.min(2,store.zoom+.1)"><ZoomIn/></button></div><div ref="mapViewport" class="map-viewport"><div class="map-stage-wrap"><div class="map-stage" :class="{'hide-grid':!store.showGrid}" :style="canvasStyle"><button v-for="(tile,index) in store.terrain" :key="index" class="map-cell" :style="tileStyle(tile)" :aria-label="`Tile ${index%project.width+1}, ${Math.floor(index/project.width)+1}: ${terrainById[tile]?.label}`" @pointerdown.prevent="beginCell(index%project.width,Math.floor(index/project.width))" @pointerenter="enterCell(index%project.width,Math.floor(index/project.width))"></button><template v-if="layerVisible('structure')"><span v-for="item in store.bundle.structures.filter(item=>!item.deletedAt)" :key="item.id" class="map-structure" :class="item.kind" :style="{left:`${item.x*cellSize}px`,top:`${item.y*cellSize}px`,width:`${cellSize}px`,height:`${cellSize}px`}"></span></template><template v-if="layerVisible('objects')"><button v-for="item in store.visibleObjects" :key="item.id" class="placed-object" :class="{selected:store.selection?.id===item.id}" :style="objectStyle(item)" :aria-label="objectById[item.assetId]?.label" @pointerdown.stop="selectObject($event,item)"></button></template><template v-if="layerVisible('labels')"><button v-for="item in store.visibleLabels" :key="item.id" class="map-label" :class="[item.size,{selected:store.selection?.id===item.id}]" :style="{left:`${item.x*cellSize}px`,top:`${item.y*cellSize}px`}" @pointerdown.stop="selectLabel($event,item)">{{item.text}}</button></template></div></div></div></section><aside class="map-inspector"><div class="inspector-tabs"><button :class="{active:inspectorTab==='layers'}" @click="inspectorTab='layers'"><Layers3/>Layers</button><button :class="{active:inspectorTab==='selection'}" @click="inspectorTab='selection'"><MousePointer2/>Selection</button></div><div v-if="inspectorTab==='layers'" class="inspector-panel"><h2>Map layers</h2><p>Control what appears in the editor and exports.</p><div class="layer-list"><button v-for="layer in [...store.bundle.layers].reverse()" :key="layer.id" @click="store.toggleLayer(layer.id)"><Eye v-if="layer.visible"/><EyeOff v-else/><span><strong>{{layer.name}}</strong><small>{{layer.kind}}</small></span></button></div><div class="map-summary"><Map/><div><strong>{{project.width}} × {{project.height}}</strong><span>{{store.visibleObjects.length}} objects · {{store.visibleLabels.length}} labels</span></div></div></div><div v-else-if="store.selectedEntity" class="inspector-panel"><span class="modal-eyebrow">{{store.selection.kind}}</span><h2>{{store.selection.kind==='object'?objectById[store.selectedEntity.assetId]?.label:store.selectedEntity.text}}</h2><div v-if="store.selection.kind==='label'" class="field"><label>Text</label><input :value="store.selectedEntity.text" maxlength="200" @change="store.updateEntity({text:$event.target.value})"></div><div class="field-row"><div class="field"><label>X</label><input :value="store.selectedEntity.x" type="number" @change="store.updateEntity({x:Number($event.target.value)})"></div><div class="field"><label>Y</label><input :value="store.selectedEntity.y" type="number" @change="store.updateEntity({y:Number($event.target.value)})"></div></div><div v-if="store.selection.kind==='object'" class="field"><label>Rotation</label><input :value="store.selectedEntity.rotation" type="range" min="0" max="315" step="45" @change="store.updateEntity({rotation:Number($event.target.value)})"></div><label class="check-row"><input :checked="store.selectedEntity.hidden" type="checkbox" @change="store.updateEntity({hidden:$event.target.checked})"><span>Hide in player view</span></label><button class="button danger inspector-delete" @click="store.deleteSelection"><Trash2/>Remove from map</button></div><div v-else class="inspector-empty"><MousePointer2/><h3>Nothing selected</h3><p>Choose an object or label on the map to edit it.</p></div></aside></section></main></template>
